// Scoped local connector: no arbitrary URLs, platforms, documents or DB access.
function createAloBridge({equal,rpc,readJob,verify,validConsent,now=()=>Date.now()}) {
 const uuid=v=>typeof v==='string'&&/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(v);
 const json=(body,status=200)=>Response.json(body,{status,headers:{'cache-control':'no-store'}});
 const allowed=async(job,env)=>job?.platform==='ALO'&&job.status==='running'&&uuid(job.id)&&uuid(job.lease_id)&&Date.parse(job.lease_until)>now()+1000&&validConsent(job.consent,now())&&await verify(job,env,{now:now()});
 const unavailable=()=>({platform:'ALO',availability:'unavailable',reason:'SOURCE_AUTHORIZATION_NOT_CURRENT',creditDecision:null});
 function safeObservation(o,job){
  if(o?.platform!=='ALO'||o.creditDecision!==null)return null;
  if(o.availability==='unavailable'&&['PROVIDER_HTTP_401','PROVIDER_HTTP_403','PROVIDER_HTTP_404','PROVIDER_HTTP_429','PROVIDER_HTTP_5XX','PROVIDER_REQUEST_FAILED','INVALID_PROVIDER_RESPONSE','PROVIDER_INFORMATION_UPDATING','PROVIDER_TIMEOUT','PROVIDER_UNAVAILABLE','UNSUPPORTED_DOCUMENT'].includes(o.reason))return {platform:'ALO',availability:'unavailable',reason:o.reason,creditDecision:null};
  const date=Date.parse(o.checkedAt);
  if(o.availability!=='observed'||!Number.isFinite(date)||date>now()+5000||date<now()-90000||!Number.isInteger(o.reportedProducts)||o.reportedProducts<0||o.reportedProducts>20)return null;
  if(o.reportedProducts===0&&o.reason!=='ALO_NO_ACTIVE_OBLIGATIONS_REPORTED')return null;
  if(o.reportedProducts>0&&o.reason)return null;
  let details;try{details=novaPaymentExtensions.validatedAloDetails(o);}catch{return null;}
  return {platform:'ALO',availability:'observed',checkedAt:new Date(date).toISOString(),reportedProducts:o.reportedProducts,
   ...(details?{detailVersion:1,productDetails:details}:{}),
   ...(o.reportedProducts===0?{reason:o.reason}:{paymentInProgress:o.paymentInProgress===true}),
   identityStatus:o.reportedProducts===0?'queried_document':'provider_match_requires_case_verification',remainingBalance:null,dueDate:null,creditDecision:null};
 }
 return async function handle(request,env,bounded){
  if(!env.NOVA_ALO_LOCAL_TOKEN||!await equal(request.headers.get('authorization')?.replace(/^Bearer /,''),env.NOVA_ALO_LOCAL_TOKEN))return json({error:'UNAUTHORIZED'},401);
  if(request.method!=='POST')return json({error:'METHOD_NOT_ALLOWED'},405);
  if(env.NOVA_PLATFORM_EXECUTION_ENABLED!=='true'||env.NOVA_ALO_READ_ENABLED!=='true')return json({error:'DISABLED'},503);
  try {
   const action=new URL(request.url).pathname.split('/').pop();
   if(action==='claim'){
    const jobs=await rpc(env)('nova_claim_platform_jobs',{p_platforms:['ALO']});
    if(!Array.isArray(jobs)||jobs.length>2)throw Error('INVALID_BATCH');
    const out=[];
    for(const job of jobs){
     if(!await allowed(job,env)){await rpc(env)('nova_finish_platform_job',{p_id:job.id,p_lease_id:job.lease_id,p_observation:unavailable()});continue;}
     out.push({id:job.id,lease_id:job.lease_id,lease_until:job.lease_until,document:job.inputs.document});
    }
    return json({jobs:out});
   }
   if(!['check','finish'].includes(action))return json({error:'NOT_FOUND'},404);
   const body=await bounded(request,8192);
   if(!uuid(body?.id)||!uuid(body.lease_id))return json({error:'INVALID_JOB'},400);
   const job=await readJob(body.id,env);
   if(!job||job.platform!=='ALO'||job.lease_id!==body.lease_id||job.status!=='running'||Date.parse(job.lease_until)<=now())return json({error:'STALE_LEASE'},409);
   const current=await allowed(job,env);
   if(action==='check')return json({allowed:current});
   const observation=current?safeObservation(body.observation,job):unavailable();
   if(!observation)return json({error:'INVALID_OBSERVATION'},400);
   return json(await rpc(env)('nova_finish_platform_job',{p_id:job.id,p_lease_id:job.lease_id,p_observation:observation}));
  }catch{return json({error:'CONNECTOR_UNAVAILABLE'},503);}
 };
}

