// Internal portfolio inventory only. Never invokes Meta, provider or credit job queues.
function createKrediyaPreparation({boundedJson,equal,readInventory,now=()=>Date.now()}){
 const key='nova:krediya:portfolio-preparation:v1';
 const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;
 async function scan(env,{force=false,readRows=readInventory}={}){
  if(!env.NOVA_EVENTS||!env.KORA_READONLY?.connectionString)return {ready:false,reason:'INVENTORY_NOT_CONFIGURED'};
  const old=await env.NOVA_EVENTS.get(key,'json');
  if(!force&&old?.checkedAt&&now()-Date.parse(old.checkedAt)<86400000)return {cached:true};
  const rows=await readRows(env);
  if(!Array.isArray(rows)||rows.length>1000)throw Error('KREDIYA_INVENTORY_REQUIRES_PAGINATION');
  const seen=new Set(),cases=[];
  for(const row of rows){
   if(!UUID.test(row.id)||seen.has(row.id)||!UUID.test(row.ventas?.cliente_id)||row.ventas.anulada!==false)throw Error('INVALID_INVENTORY_ROW');
   seen.add(row.id);
   const contract=typeof row.contrato_ref==='string'?row.contrato_ref.trim():'';
   cases.push({creditId:row.id,clientId:row.ventas.cliente_id,storeCode:row.ventas.tienda_codigo,
    contractAvailable:!!contract,state:contract?'authorization_review_required':'contract_and_authorization_review_required'});
  }
  const snapshot={version:'20261001-v1',checkedAt:new Date(now()).toISOString(),mode:'preparation_only',providerQueries:0,
   total:cases.length,withContract:cases.filter(c=>c.contractAvailable).length,authorizationReviewRequired:cases.length,cases};
  await env.NOVA_EVENTS.put(key,JSON.stringify(snapshot),{expirationTtl:604800});
  return summary(snapshot);
 }
 function summary(s){if(!s)return {ready:false,reason:'NOT_SCANNED'};const {cases,...safe}=s;return {...safe,ageHours:Math.max(0,Math.floor((now()-Date.parse(s.checkedAt))/3600000)),stale:now()-Date.parse(s.checkedAt)>86400000};}
 async function handle(request,env){
  const token=request.headers.get('authorization')?.replace(/^Bearer /,'');
  if(!env.NOVA_INTERNAL_API_TOKEN||!await equal(token,env.NOVA_INTERNAL_API_TOKEN))return new Response('Unauthorized',{status:401});
  if(!['GET','POST'].includes(request.method))return new Response('Method not allowed',{status:405});
  try{
   const result=request.method==='POST'?await scan(env,{force:true}):summary(await env.NOVA_EVENTS?.get(key,'json'));
   return Response.json({...result,executorEnabled:env.NOVA_KREDIYA_EXECUTOR_ENABLED==='true',transportVerified:env.NOVA_KREDIYA_TRANSPORT_VERIFIED==='true'},{headers:{'cache-control':'no-store'}});
  }catch{return Response.json({ready:false,reason:'PREPARATION_UNAVAILABLE'},{status:503});}
 }
 return {scan,handle};
}

